//
//  StoreScreenshotFixtures.swift
//  ios
//
//  DEBUG-ONLY sample data for `StoreScreenshotMode` (read that file's header first).
//
//  Every figure here is INVENTED. Prices, % moves and sparklines are sample values shown under
//  the "Sample data" label, never market data. Series are generated by a formula, not typed out,
//  so the file holds no large literal (a giant Swift literal crashed this Mac: CLAUDE.md,
//  Machine safety rule 7).
//
//  Wire fixtures are built with JSONSerialization in the shape the backend's response models
//  emit, so they travel through the app's real decoders and mappers:
//    GET  /api/v1/tracking/assets          → schemas/tracking.py      TrackingFeedResponse
//    GET  /api/v1/portfolios               → endpoints/portfolios.py  PortfolioListResponse
//    GET  /api/v1/portfolios/{id}/insights → null (a group with no holdings has no score)
//    GET  /api/v1/updates/tabs             → schemas/updates.py       UpdatesTabsResponse
//  Writes the Tracking tab can trigger (its feed-driven ticker purge PUTs the active group's
//  tickers) are answered here and never reach the server — against a real account they would
//  delete real rows.
//

#if DEBUG
import Foundation
import SwiftUI

/// One sample holding — the same five on Home's holdings strip, the Tracking list and the
/// Updates chips, so the screenshots agree with each other.
nonisolated struct StoreShotHolding: Sendable {
    let symbol: String
    let name: String
    let price: Double
    let changePercent: Double
    let marketCap: Double
    let sector: String
}

nonisolated enum StoreShotFixtures {
    static let portfolioId = "store-shot-sample"
    /// Shown as the group name on Tracking, Updates and Home — the label lives in the data too.
    static let groupName = "Sample data"

    static let holdings: [StoreShotHolding] = [
        StoreShotHolding(symbol: "AAPL", name: "Apple Inc.", price: 184.20, changePercent: 1.24,
                         marketCap: 2.84e12, sector: "Technology"),
        StoreShotHolding(symbol: "MSFT", name: "Microsoft Corporation", price: 412.50, changePercent: 0.86,
                         marketCap: 3.07e12, sector: "Technology"),
        StoreShotHolding(symbol: "NVDA", name: "NVIDIA Corporation", price: 131.80, changePercent: 2.41,
                         marketCap: 3.24e12, sector: "Technology"),
        StoreShotHolding(symbol: "AMZN", name: "Amazon.com, Inc.", price: 178.40, changePercent: -0.52,
                         marketCap: 1.87e12, sector: "Consumer Cyclical"),
        StoreShotHolding(symbol: "GOOGL", name: "Alphabet Inc.", price: 162.30, changePercent: 0.37,
                         marketCap: 2.01e12, sector: "Communication Services"),
    ]

    static func previousClose(of holding: StoreShotHolding) -> Double {
        holding.price / (1.0 + holding.changePercent / 100.0)
    }

    /// A smooth, deterministic intraday-shaped series from `start` to exactly `end`.
    static func series(seed: Int, count: Int, from start: Double, to end: Double) -> [Double] {
        var points: [Double] = []
        points.reserveCapacity(count)
        let span: Double = max(abs(end - start), start * 0.004)
        let phase: Double = Double(seed) * 1.7
        let last: Double = Double(max(count - 1, 1))
        for index in 0..<count {
            let t: Double = Double(index) / last
            let trend: Double = start + (end - start) * t
            let slow: Double = sin(t * 7.0 + phase) * 0.45
            let fast: Double = sin(t * 19.0 + phase * 2.3) * 0.2
            let taper: Double = 1.0 - t
            points.append(trend + (slow + fast) * span * taper)
        }
        return points
    }

    static func sparkline(for holding: StoreShotHolding, seed: Int) -> [Double] {
        series(seed: seed, count: 40, from: previousClose(of: holding), to: holding.price)
    }

    // MARK: Wire fixtures

    static func trackingFeedJSON() -> Data {
        var assets: [[String: Any]] = []
        for (index, holding) in holdings.enumerated() {
            var row: [String: Any] = [:]
            row["ticker"] = holding.symbol
            row["company_name"] = holding.name
            row["price"] = holding.price
            row["change_percent"] = holding.changePercent
            row["price_known"] = true
            row["change_known"] = true
            row["previous_close"] = previousClose(of: holding)
            row["sparkline_data"] = sparkline(for: holding, seed: index)
            row["spark_from"] = 0.0
            row["spark_to"] = 1.0
            row["logo_url"] = NSNull()
            row["sector"] = holding.sector
            row["country"] = "US"
            row["market_cap"] = holding.marketCap
            // No holding values: these are watchlist rows, so the holding fields are null.
            row["shares"] = NSNull()
            row["market_value"] = NSNull()
            row["asset_type"] = NSNull()
            assets.append(row)
        }
        let body: [String: Any] = ["assets": assets, "alerts": [Any]()]
        return json(body)
    }

    static func portfolioObject() -> [String: Any] {
        var items: [[String: Any]] = []
        for holding in holdings {
            items.append(["ticker": holding.symbol, "shares": NSNull(), "market_value": NSNull()])
        }
        var portfolio: [String: Any] = [:]
        portfolio["id"] = portfolioId
        portfolio["name"] = groupName
        portfolio["sort_order"] = 0
        portfolio["items"] = items
        portfolio["created_at"] = "2026-10-01T00:00:00Z"
        portfolio["updated_at"] = "2026-10-01T00:00:00Z"
        portfolio["is_active"] = true
        return portfolio
    }

    static func portfoliosJSON() -> Data {
        json(["portfolios": [portfolioObject()]])
    }

    /// The answer to any portfolio WRITE: the unchanged sample group (`PortfolioResponse`).
    static func portfolioJSON() -> Data {
        json(portfolioObject())
    }

    static func updatesTabsJSON() -> Data {
        var tabs: [[String: Any]] = []
        var market: [String: Any] = [:]
        market["scope"] = "__MARKET__"
        market["title"] = "Market"
        market["company_name"] = NSNull()
        market["change_percent"] = NSNull()
        market["logo_url"] = NSNull()
        market["is_market_tab"] = true
        market["is_locked"] = false
        market["asset_type"] = NSNull()
        tabs.append(market)
        for holding in holdings {
            var tab: [String: Any] = [:]
            tab["scope"] = holding.symbol
            tab["title"] = holding.symbol
            tab["company_name"] = holding.name
            tab["change_percent"] = holding.changePercent
            tab["logo_url"] = NSNull()
            tab["is_market_tab"] = false
            tab["is_locked"] = false
            tab["asset_type"] = "stock"
            tabs.append(tab)
        }
        var body: [String: Any] = [:]
        body["tabs"] = tabs
        body["group_name"] = groupName
        body["locked_count"] = 0
        body["tier_required"] = NSNull()
        return json(body)
    }

    private static func json(_ object: Any) -> Data {
        do {
            return try JSONSerialization.data(withJSONObject: object)
        } catch {
            print("📸 [StoreScreenshotMode] fixture encode failed: \(type(of: error)): \(error)")
            return Data("{}".utf8)
        }
    }
}

