    }

    // MARK: Market strip (invented values)

    private static var samplePulse: [MarketPulseItem] {
        var items: [MarketPulseItem] = []
        items.append(pulseItem("S&P 500 ETF", "SPY", .etf, price: 512.40, change: 0.48, seed: 11))
        items.append(pulseItem("Nasdaq ETF", "ONEQ", .etf, price: 68.20, change: 0.71, seed: 12))
        items.append(pulseItem("Dow Jones ETF", "DIA", .etf, price: 421.30, change: 0.22, seed: 13))
        items.append(pulseItem("Russell 2000 ETF", "IWM", .etf, price: 205.60, change: -0.35, seed: 14))
        items.append(pulseItem("Gold ETF", "GLD", .etf, price: 231.80, change: 0.15, seed: 15))
        items.append(pulseItem("Bitcoin", "BTCUSD", .crypto, price: 64_250.00, change: 1.10, seed: 16))
        return items
    }

    private static func pulseItem(
        _ name: String, _ symbol: String, _ type: MarketTickerType,
        price: Double, change: Double, seed: Int
    ) -> MarketPulseItem {
        let previous: Double = price / (1.0 + change / 100.0)
        let priceText: String = price >= 10_000
            ? price.formatted(.number.precision(.fractionLength(2)))
            : String(format: "%.2f", price)
        return MarketPulseItem(
            name: name, symbol: symbol, type: type,
            priceText: priceText, changeText: percentText(change), isPositive: change >= 0,
            spark: StoreShotFixtures.series(seed: seed, count: 30, from: previous, to: price),
            previousClose: previous
        )
    }

    private static func percentText(_ change: Double) -> String {
        (change >= 0 ? "+" : "") + String(format: "%.2f%%", change)
    }

    // MARK: Daily Scanners (invented values)

    private static func entry(
        _ rank: Int, _ symbol: String, _ name: String,
        _ primary: String, _ secondary: String, _ up: Bool
    ) -> ScannerEntry {
        ScannerEntry(rank: rank, symbol: symbol, name: name,
                     primaryText: primary, secondaryText: secondary, isPositive: up)
    }

    /// Rank 1 carries the card's sparkline.
    private static func head(_ entry: ScannerEntry, seed: Int, rising: Bool) -> ScannerEntry {
        var withSpark = entry
        let low: Double = 100
        let high: Double = 106
        withSpark.spark = StoreShotFixtures.series(seed: seed, count: 30, from: rising ? low : high, to: rising ? high : low)
        return withSpark
    }

